/**
 * @method
 * @name scwin.tx_fn_openChrgDetlCnfm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_openChrgDetlCnfm = async function () {
    const sbmOptions = {
        id: "tx_fn_openChrgDetlCnfm",
        method: "post",
        action: "/strip/strip.do?method=searchStripChrgDetl",
        ref: "dma_openChrgDetlCnfmReq",
        target: "dlt_bndApctTpCdList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldbnf30100.tx_fn_openChrgDetlCnfm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
