 * @name scwin.mpd_files_selectCallback
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name scwin.openChrgDetlCnfm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.openChrgDetlCnfm = async function () {
    /* sdd-asis-lifecycle:begin fn_openChrgDetlCnfm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_sprtParAmt').getValue()) == 0 && $c.str.getByteLength($c.util.getComponent('ipt_recombinParAmt').getValue()) == 0) {
        await $c.win.alert("분리신청액면금액 또는 재결합신청액면금액을 입력하십시오.");
        $c.util.getComponent("ipt_sprtParAmt").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_sprtParAmt').getValue()) > 0 && $c.str.getByteLength($c.util.getComponent('cal_bndAddSprtDd').getValue()) == 0) {
            await $c.win.alert("추가분리일을 입력하십시오.");
            $c.util.getComponent("cal_bndAddSprtDd").focus();
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_recombinParAmt').getValue()) > 0 && $c.str.getByteLength($c.util.getComponent('cal_recombinEfctOccrDd').getValue()) == 0) {
                await $c.win.alert("재결합효력발생일을 입력하십시오.");
                $c.util.getComponent("cal_recombinEfctOccrDd").focus();
                return false;
            }
        }
    }
    $c.util.getComponent("ipt_cnfmYn").setValue("N");
    const width = 1000;
    const height = 800;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/strip/strip.do?method=searchStripChrgDetl", unresolved: "nav:" + "/strip/strip.do?method=searchStripChrgDetl" }; })();
    fm.action = '/strip/strip.do?method=searchStripChrgDetl';

    return;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    $c.util.getComponent("slc_bndApctTpCd").setValue("1");
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    $c.util.getComponent("dma_openChrgDetlCnfmReq").set("apctTelNo", $c.util.getComponent('ipt_apctTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo3').getValue());
    $c.util.getComponent("dma_openChrgDetlCnfmReq").set("apctFaxNo", $c.util.getComponent('ipt_apctFaxNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo3').getValue());
    $c.util.getComponent("dma_openChrgDetlCnfmReq").set("encrypApctEmail", $c.util.getComponent('ipt_encrypApctEmail1').getValue()+ '@' + $c.util.getComponent('ipt_encrypApctEmail2').getValue());
    fm.action = '/strip/strip.do?method=saveStripAddMerge';
    fm.target = '_self';
    await scwin.tx_fn_save();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkData = async function () {
    /* sdd-asis-lifecycle:begin fn_checkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('cal_procsReqDd').getValue()) == 0) {
        await $c.win.alert("적용희망일을 입력하십시오.");
        $c.util.getComponent("cal_procsReqDd").focus();
        return false;
    } else {
        if (WebSquare.date.getCurrentServerDate("yyyyMMdd") >= $c.util.getComponent('cal_procsReqDd').getValue().replace("-", "").replace("-", "")) {
            await $c.win.alert("적용희망일은 익일 이후만 입력가능합니다.");
            $c.util.getComponent("cal_procsReqDd").focus();
            return;
        } else {
            if ($c.util.getComponent('ipt_cnfmYn').getValue()!== "Y") {
                await $c.win.alert("신청후 변경내역 확인창 버튼을 클릭하여 변경내역을 확인하십시오.");
                return false;
            } else {
                if (!!!(($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount && ($c.util.getComponent('dlt_files')).getRowCount() > 0)) {
                    return false;
                } else {
                    if (!CheckReqInfo(fm)) {
                        return false;
                    }
                }
            }
        }
    }
    const totFileSize = (Math.round(((($c.util.getComponent('dlt_files')) && ($c.util.getComponent('dlt_files')).getRowCount) ? Array.from({ length: ($c.util.getComponent('dlt_files')).getRowCount() }, function (x, i) { return Number(($c.util.getComponent('dlt_files')).getCellData(i, 'FILE_SIZE')) || 0; }).reduce(function (a, b) { return a + b; }, 0) : 0) / (1024 * 1024) * 100) / 100);
    if (totFileSize > 100) {
        await $c.win.alert("전체 첨부파일의 크기는 최대 100MB까지 허용됩니다.\n현재 크기 = " + totFileSize + "MB");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


